def transform(grid):
    h, w = len(grid), len(grid[0])

    # Repeating horizontal bands: uniform nonzero rows give the known pattern.
    row_values = {}
    for r, row in enumerate(grid):
        if all(x == row[0] for x in row) and row[0] != 0:
            row_values[r] = row[0]

    if row_values:
        for p in range(1, h + 1):
            pattern = {}
            valid = True
            for r, value in row_values.items():
                phase = r % p
                if phase in pattern and pattern[phase] != value:
                    valid = False
                    break
                pattern[phase] = value
            if valid and len(pattern) == p:
                return [[pattern[r % p] for _ in range(w)] for r in range(h)]

    # Otherwise, repeat colors along diagonals (constant column - row).
    for p in range(1, max(h, w) + 1):
        pattern = {}
        valid = True
        for r in range(h):
            for c in range(w):
                value = grid[r][c]
                if value == 0:
                    continue
                phase = (c - r) % p
                if phase in pattern and pattern[phase] != value:
                    valid = False
                    break
                pattern[phase] = value
            if not valid:
                break
        if valid and len(pattern) == p:
            return [[pattern[(c - r) % p] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
